questionvariables.text:
clist: [[0,"ABCD","AC",7.6,2.8,1.9],[1,"ABFE","AF",54,32,7],[2,"BCGF","BG",7.4,2.6,3.9],[3,"ABCD","AC",38,11,23],[0,"ABFE","AF",4.5,4.3,2.4],[1,"BCGF","BG",52,34,16],[2,"ABCD","AC",3.7,5.6,1.6],[3,"ABFE","AF",43,32,13],[0,"BCGF","BG",5,3.2,3.5],[1,"ABCD","AC",53,8,15]];
/* Design: diagonals and projections in a cuboid (Pythagoras twice). The projection is not named in the stem. j picks the plane: ABCD (projection AC, G lands at C, third side GC), ABFE (AF, F, GF), BCGF (BG, A lands at B, third side AB). Source: adapted from SMP GCSE Higher 2, Chapter 34, Section B worked example and B3. */
CT: [["A water tank","m"],["A carton","cm"],["A store room","m"],["A wooden box","cm"]];
ix: 1+rand(10); CC: clist[ix];
ctx: CT[CC[1]+1][1]; un: CT[CC[1]+1][2]; pl: CC[2]; prj: CC[3]; ll: CC[4]; ww: CC[5]; hh: CC[6];
LS: "ABCDEFGH"; LT: [[0,0,0],[ll,0,0],[ll,ww,0],[0,ww,0],[0,0,hh],[ll,0,hh],[ll,ww,hh],[0,ww,hh]];
pt(c) := LT[ssearch(c, LS)];
vv(s) := pt(charat(s,2)) - pt(charat(s,1));
sq(s) := vv(s) . vv(s);
dst(s) := float(sqrt(sq(s)));
angd(s) := block([u,w], u: pt(charat(s,1))-pt(charat(s,2)), w: pt(charat(s,3))-pt(charat(s,2)), float(acos((u . w)/sqrt((u . u)*(w . w)))*180/%pi));
r1(v) := float(floor(10*v+1/2)/10); r2(v) := float(floor(100*v+1/2)/100);
d1(v) := dispdp(r1(v),1); d2(v) := dispdp(r2(v),2); d4(v) := dispdp(float(floor(10000*v+1/2)/10000),4);
NA: -999; NB: -888; NC: -777;
nf(v) := if integerp(v) then v else float(v);
r4(v) := float(floor(10000*v+1/2)/10000);
PLS: ["ABCD","ABFE","BCGF"]; PJS: ["AC","AF","BG"]; FTS: ["G lands at C","G lands at F","A lands at B"]; THS: ["GC","GF","AB"];
j: first(sublist([1,2,3], lambda([k], is(PLS[k] = pl))));
ot: delete(j, [1,2,3]); op1: PJS[ot[1]]; ol1: PLS[ot[1]]; op2: PJS[ot[2]]; ol2: PLS[ot[2]];
foot: FTS[j]; thd: THS[j]; third: dst(thd);
cmp: sublist(map(abs, vv(prj)), lambda([t], is(t > 0))); ca: cmp[1]; cb: cmp[2];
S1: r4(sq(prj)); S2: r4(sq("AG")); t1: dst(prj); t2: dst("AG");
g1: dst(op1); g2: dst(op2); sm: ca+cb; nr1: sq(prj);
nr2: sq("AG"); sall: ll+ww+hh; ad: t1+third;
t1r: r2(t1); t2r: r2(t2); t1a: t1+0.02; t2a: t2+0.02; t2g: t2+0.5;
fa: t1+1; fb: float(sqrt(fa^2+third^2));
